/* "Which city would you like to receive the supplies?" -- cancel a filed
 * supplies request, or pick one of the side's own cities and file one. */
void opeu_request_supplies(uint8_t ds[65536], HostEvent event,
                           uint16_t scratch) {
  CITY_PTR dest;

  BUFFER(buffer, 50, 4);
  RequestSlotView order;
  if (PENDING(0)) {
    if (!CANCEL(SUPPLIES_TEXT))
      return;
    FILED_KIND(0) = 0xff;
  }
  TITLE(TITLE_TEXT);
  X = VIEW_X;
  Y = VIEW_Y;
  MESSAGE(WHERE_TEXT, RECORD2);
  for (;;) {
    if (!PICK())
      return;
    dest = FIND(X, Y);
    if (dest && CITY_SIDE(dest) == SIDE)
      break;
  }
  FORMAT(buffer, CONFIRM_TEXT, dest);
  if (!CONFIRM(buffer, RECORD2))
    return;
  order.target   = TARGET_OF(dest);
  order.argument = 0xff;
  order.kind     = 0;
  FILE_REQUEST(order);
  DELAY(SIDE) = 1;
}

